// ============================================================
// Rule: THM_Nailaolocker Mutex "lockv7" Detected
// Vendor: Windows
// Objective:
// Detect activity associated with THM_Nailaolocker Mutex "lockv7" Detected.
// Severity: SEV_050_CRITICAL
// Category: DISCOVERY
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0007 - Discovery
// Technique: T1057 - Process Discovery

// Desabilita diferenciação entre maiúsculas e minúsculas para comparações
config case_sensitive = false  

// Define o dataset de origem como dados brutos do Cortex XDR
| dataset = xdr_data  

// Filtra apenas eventos de chamadas de sistema (syscalls)
| filter event_type = ENUM.SYSTEM_CALL  

// Restringe aos eventos específicos de criação de "mutants" (objetos de sincronização no Windows)
| filter event_sub_type = ENUM.SYSTEM_CALL_NT_CREATE_MUTANT  

// Extrai o valor do mutex criado a partir dos parâmetros da syscall
| alter mutex = json_extract_scalar(action_syscall_string_params, "$.1")  

// Filtra apenas quando o mutex criado corresponde a "lockv7"
// (exemplo comum usado por algumas famílias de malware para evitar múltiplas execuções)
| filter mutex = "lockv7"  

// Seleciona os campos relevantes para análise
| fields _time,                              // Momento do evento
         agent_hostname,                     // Nome do host onde ocorreu a execução
         actor_process_image_name,           // Nome do processo que criou o mutex
         actor_process_image_path,           // Caminho completo do processo
         actor_process_command_line,         // Linha de comando usada na execução
         mutex                               // Nome do mutex identificado
